import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 2

def design(feats):
    # Identify strong candidates using t-test and correlation
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        t_stat = feats.x[:, i].mean() * np.sqrt(len(feats.x))
        p_val = 2 * (1 - stats.norm.cdf(abs(t_stat)))
        if p_val < 0.05:
            candidates.append((fid, abs(t_stat)))

    # Sort by strength
    candidates.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    selected = []
    excluded = set()
    for fid, _ in candidates[:10]:  # Limit to top 10
        if fid in excluded:
            continue
        selected.append(fid)
        # Mark correlated features as excluded
        for other_fid, corr in [(f, np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(f)])[0,1]) 
                               for f in feats.ids if f != fid and abs(np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(f)])[0,1]) >= 0.6]:
            if abs(corr) >= 0.6:
                excluded.add(other_fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # If no strong candidates found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    columns = tuple(selected)
    loadings = {fid: 1.0 for fid in selected}

    # Check for interactions between top features
    products = []
    if len(selected) >= 2:
        # Add interaction terms for top two features
        products = [(selected[0], selected[1])]

    return Design(drivers=tuple(selected), columns=columns, products=products, loadings=loadings)

